create sequence emdb_media.movie_sequence start with 1 increment by 1;
create sequence emdb_media.person_sequence start with 1 increment by 1;
create sequence emdb_media.series_sequence start with 1 increment by 1;
create table emdb_media.credits (credit_order integer, credit_type varchar(4) not null check ((credit_type in ('CAST','CREW'))), total_episodes integer, createdAt timestamp(6) with time zone not null, modifiedAt timestamp(6) with time zone not null, movie_id bigint not null, person_id bigint not null, series_id bigint, id uuid not null, DTYPE varchar(31) not null check ((DTYPE in ('MovieCredit','SeriesCredit'))), role varchar(100), external_id varchar(255) unique, primary key (id));
create table emdb_media.movies (original_language varchar(2) not null, release_date date, runtime integer, score float4 not null check ((score<=10) and (score>=0)), budget bigint, createdAt timestamp(6) with time zone not null, external_id bigint not null unique, id bigint not null, modifiedAt timestamp(6) with time zone not null, revenue bigint, backdrop uuid unique, poster uuid unique, status varchar(16) not null check ((status in ('CANCELED','ENDED','IN_PRODUCTION','PILOT','PLANNED','POST_PRODUCTION','RELEASED','RETURNING_SERIES','RUMORED'))), title varchar(140) not null, tagline varchar(150), overview varchar(1024), homepage varchar(2048), primary key (id), constraint uq_movies_title_release_date unique (title, release_date));
create table emdb_media.people (birth_date date, death_date date, createdAt timestamp(6) with time zone not null, external_id bigint not null unique, id bigint not null, modifiedAt timestamp(6) with time zone not null, gender varchar(10) not null check ((gender in ('UNKNOWN','FEMALE','MALE','NON_BINARY'))), profile uuid unique, name varchar(80) not null, birth_place varchar(120), homepage varchar(2048), biography varchar(3900), primary key (id));
create table emdb_media.Roles (episode_count integer not null, createdAt timestamp(6) with time zone not null, modifiedAt timestamp(6) with time zone not null, id uuid not null, series_credit_id uuid not null, role varchar(100), external_id varchar(255) not null unique, primary key (id));
create table emdb_media.series (first_air_date date, original_language varchar(2) not null, score float4 not null check ((score<=10) and (score>=0)), createdAt timestamp(6) with time zone not null, external_id bigint not null unique, id bigint not null, modifiedAt timestamp(6) with time zone not null, type varchar(11) check ((type in ('SCRIPTED','REALITY','DOCUMENTARY','NEWS','TALK_SHOW','MINISERIES','VIDEO'))), backdrop uuid unique, poster uuid unique, status varchar(16) not null check ((status in ('CANCELED','ENDED','IN_PRODUCTION','PILOT','PLANNED','POST_PRODUCTION','RELEASED','RETURNING_SERIES','RUMORED'))), title varchar(140) not null, tagline varchar(150), overview varchar(1024), homepage varchar(2048), primary key (id), constraint uq_series_title_first_air_date unique (title, first_air_date));
alter table if exists emdb_media.Roles add constraint FKm1yl5kyk42se8cjhon3b13wt8 foreign key (series_credit_id) references emdb_media.credits;
